{"implementation":"import math

def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty array")
    if not isinstance(required_symbols, list) or any(
        not isinstance(symbol, str) for symbol in required_symbols
    ):
        raise ValueError("required_symbols must be an array of strings")

    by_id = {}
    order = []
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node is missing a required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node ids must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be a string or null")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be a boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        try:
            if not math.isfinite(utility):
                raise ValueError("utility must be finite")
        except OverflowError:
            raise ValueError("utility must be finite")
        by_id[node_id] = node
        order.append(node_id)

    roots = []
    children = {node_id: [] for node_id in order}
    for node_id in order:
        node = by_id[node_id]
        parent = node["parent"]
        if parent is None:
            roots.append(node_id)
            if node["depth"] != 0:
                raise ValueError("root depth must be zero")
        else:
            if parent not in by_id:
                raise ValueError("parent does not exist")
            if parent == node_id:
                raise ValueError("node cannot parent itself")
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("node depth is inconsistent with parent")
            children[parent].append(node_id)
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")

    root_id = roots[0]
    for node_id in order:
        seen = set()
        current = node_id
        while by_id[current]["parent"] is not None:
            current = by_id[current]["parent"]
            if current in seen:
                raise ValueError("parent graph contains a cycle")
            seen.add(current)
        if current != root_id:
            raise ValueError("node is disconnected from root")

    required = set(required_symbols)
    represented = {node["symbol"] for node in nodes}
    if not required.issubset(represented):
        raise ValueError("a required symbol is not represented")

    retained = set(order)
    removed = []
    candidates = sorted(order, key=lambda node_id: (-by_id[node_id]["depth"], node_id))
    for node_id in candidates:
        node = by_id[node_id]
        if node_id == root_id or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        remaining_symbols = {
            by_id[other_id]["symbol"]
            for other_id in retained
            if other_id != node_id
        }
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
